python3 -c "
sols = []
N = 500
for a in range(2, N+1):
    for b in range(a, N+1):
        for c in range(b, N+1):
            v1 = a*b - c
            v2 = b*c - a
            v3 = c*a - b
            if v1 <= 0 or v2 <= 0 or v3 <= 0:
                continue
            def ispow2(n):
                return n > 0 and (n & (n-1)) == 0
            if ispow2(v1) and ispow2(v2) and ispow2(v3):
                sols.append((a,b,c,v1,v2,v3))
for s in sols:
    print(s)
"
